import sys
from collections import deque

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)

    n = int(next(iterator))
    m = int(next(iterator))
    q = int(next(iterator))

    grid = []
    for _ in range(n):
        row = []
        for _ in range(m):
            row.append(int(next(iterator)))
        grid.append(row)

    queries = []
    for _ in range(q):
        l = int(next(iterator))
        r = int(next(iterator))
        queries.append((l, r))

    results = []

    for l, r in queries:
        l_idx = l - 1
        r_idx = r - 1

        visited = [[False] * m for _ in range(n)]
        count = 0

        for i in range(n):
            for j in range(l_idx, r_idx + 1):
                if not visited[i][j]:
                    count += 1
                    target_val = grid[i][j]
                    queue = deque()
                    queue.append((i, j))
                    visited[i][j] = True

                    while queue:
                        ci, cj = queue.popleft()

                        for ni, nj in [(ci-1, cj), (ci+1, cj), (ci, cj-1), (ci, cj+1)]:
                            if 0 <= ni < n and l_idx <= nj <= r_idx:
                                if not visited[ni][nj] and grid[ni][nj] == target_val:
                                    visited[ni][nj] = True
                                    queue.append((ni, nj))

        results.append(str(count))

    sys.stdout.write('\n'.join(results) + '\n')

if __name__ == "__main__":
    solve()
